selected.compute:
options = read('/input/options')
ids = []
for n in range(2, 4):
    for group in combinations(options, n):
        candidate = sorted([record['id'] for record in group], key=lambda x: ([record['rank'] for record in options if record['id'] == x][0], x))
        if valid(candidate):
            ids = candidate
            break
    if ids:
        break
result = ids

selected.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
else:
    write('/output/selection', result)
    selection = result
if status('report') != 'sent':
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')
